<script setup lang="ts">
import { ref } from 'vue'
import { router, Link } from '@inertiajs/vue3'
import { route as ziggyRoute } from 'ziggy-js'
import { useI18n } from 'vue-i18n'

const { t } = useI18n()
const route = ziggyRoute
const confirmDialog = ref()

type Requisition = { id: number; uuid: string; requisition_number: string; title: string; department: string | null; job_type: { value: string; label: string }; headcount: number; reason: string; job_description: string | null; required_qualifications: string | null; required_skills: string[] | null; salary_band_min: number | null; salary_band_max: number | null; target_start_date: string | null; status: { value: string; label: string; color: string }; submitted_at: string | null; approved_at: string | null; rejected_at: string | null; converted_at: string | null; approval_notes: string | null; rejection_reason: string | null; requested_by: { id: number; name: string } | null; approved_by: { id: number; name: string } | null; created_at: string }
const props = defineProps<{ requisition: Requisition }>()

const approveDialog = ref(false); const rejectDialog = ref(false)
const approveNotes = ref(''); const rejectReason = ref(''); const submitting = ref(false)
const status = props.requisition.status.value

function formatDate(val: string | null) { if (!val) return '—'; return new Date(val).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' }) }
function formatCurrency(val: number | null) { if (val === null) return '—'; return 'R ' + val.toLocaleString('en-ZA', { minimumFractionDigits: 0 }) }

function submitForApproval() { if (!confirm(t('recruitment_requisition_pages.confirm_submit'))) return; router.post(route('recruitment.requisitions.submit', props.requisition.uuid), {}, { preserveScroll: true }) }
function convertToVacancy() { if (!confirm(t('recruitment_requisition_pages.confirm_convert'))) return; router.post(route('recruitment.requisitions.convert', props.requisition.uuid), {}, { preserveScroll: true }) }
function cancelRequisition() { if (!confirm(t('recruitment_requisition_pages.confirm_cancel'))) return; router.post(route('recruitment.requisitions.cancel', props.requisition.uuid), {}, { preserveScroll: true }) }
function deleteRequisition() { if (!confirm(t('recruitment_requisition_pages.confirm_delete'))) return; router.delete(route('recruitment.requisitions.destroy', props.requisition.uuid), { preserveScroll: true }) }
function submitApprove() { submitting.value = true; router.post(route('recruitment.approvals.requisitions.approve', props.requisition.uuid), { notes: approveNotes.value }, { preserveScroll: true, onFinish: () => { submitting.value = false; approveDialog.value = false; approveNotes.value = '' } }) }
function submitReject() { submitting.value = true; router.post(route('recruitment.approvals.requisitions.reject', props.requisition.uuid), { reason: rejectReason.value }, { preserveScroll: true, onFinish: () => { submitting.value = false; rejectDialog.value = false; rejectReason.value = '' } }) }
</script>

<template>
  <div class="pa-6">
    <div class="d-flex align-center gap-2 mb-4">
      <VBtn icon="tabler-arrow-left" variant="text" size="small" @click="router.visit(route('recruitment.requisitions.index'))" />
      <span class="text-medium-emphasis text-body-2 cursor-pointer" @click="router.visit(route('recruitment.index'))">{{ t('recruitment_requisition_pages.breadcrumb_recruitment') }}</span>
      <VIcon icon="tabler-chevron-right" size="16" class="text-medium-emphasis" />
      <span class="text-medium-emphasis text-body-2 cursor-pointer" @click="router.visit(route('recruitment.requisitions.index'))">{{ t('recruitment_requisition_pages.breadcrumb_requisitions') }}</span>
      <VIcon icon="tabler-chevron-right" size="16" class="text-medium-emphasis" />
      <span class="text-body-2 font-weight-medium">{{ requisition.requisition_number }}</span>
    </div>

    <div class="d-flex align-start justify-space-between mb-6 flex-wrap gap-3">
      <div><div class="d-flex align-center gap-3 mb-1 flex-wrap"><h4 class="font-weight-bold" style="font-size: 1.5rem; font-weight: 700; color: #0f172a;">{{ requisition.requisition_number }}</h4><VChip :color="requisition.status.color" size="small" label variant="tonal" class="font-weight-medium">{{ requisition.status.label }}</VChip></div><p class="text-medium-emphasis mb-0">{{ requisition.title }}</p></div>
      <div class="d-flex align-center gap-2 flex-wrap">
        <template v-if="status === 'draft'"><Link :href="route('recruitment.requisitions.edit', requisition.uuid)"><VBtn variant="outlined" color="default" prepend-icon="tabler-pencil" size="small">{{ t('recruitment_requisition_pages.edit') }}</VBtn></Link><VBtn color="primary" variant="flat" prepend-icon="tabler-send" size="small" @click="submitForApproval">{{ t('recruitment_requisition_pages.submit_for_approval') }}</VBtn><VBtn color="error" variant="text" prepend-icon="tabler-trash" size="small" @click="deleteRequisition">{{ t('recruitment_requisition_pages.delete_requisition') }}</VBtn></template>
        <template v-if="status === 'pending_approval'"><VBtn color="success" variant="flat" prepend-icon="tabler-circle-check" size="small" @click="approveDialog = true">{{ t('recruitment_requisition_pages.approve') }}</VBtn><VBtn color="error" variant="outlined" prepend-icon="tabler-circle-x" size="small" @click="rejectDialog = true">{{ t('recruitment_requisition_pages.reject') }}</VBtn></template>
        <template v-if="status === 'approved'"><VBtn color="primary" variant="flat" prepend-icon="tabler-briefcase-2" size="small" @click="convertToVacancy">{{ t('recruitment_requisition_pages.convert_to_vacancy') }}</VBtn></template>
        <VBtn v-if="status !== 'cancelled' && status !== 'rejected' && status !== 'converted'" color="default" variant="text" prepend-icon="tabler-ban" size="small" @click="cancelRequisition">{{ t('recruitment_requisition_pages.cancel_requisition') }}</VBtn>
      </div>
    </div>

    <VRow>
      <VCol cols="12" lg="8">
        <VCard elevation="0" border class="mb-4" style="border-radius: 12px;"><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold"><VIcon icon="tabler-info-circle" size="18" color="primary" class="me-2" />{{ t('recruitment_requisition_pages.section_basic_info') }}</VCardTitle><VCardText class="pa-5 pt-0"><VRow dense><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1">{{ t('recruitment_requisition_pages.field_title') }}</p><p class="text-body-2 font-weight-medium mb-0">{{ requisition.title }}</p></VCol><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1">{{ t('recruitment_requisition_pages.field_department') }}</p><p class="text-body-2 font-weight-medium mb-0">{{ requisition.department ?? '—' }}</p></VCol><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1 mt-3">{{ t('recruitment_requisition_pages.field_job_type') }}</p><p class="text-body-2 font-weight-medium mb-0">{{ requisition.job_type.label }}</p></VCol><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1 mt-3">{{ t('recruitment_requisition_pages.field_headcount') }}</p><div class="d-flex align-center gap-1"><VIcon icon="tabler-users" size="16" class="text-medium-emphasis" /><p class="text-body-2 font-weight-medium mb-0">{{ requisition.headcount }}</p></div></VCol><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1 mt-3">{{ t('recruitment_requisition_pages.field_target_start') }}</p><p class="text-body-2 font-weight-medium mb-0">{{ formatDate(requisition.target_start_date) }}</p></VCol><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1 mt-3">{{ t('recruitment_requisition_pages.table_requested_by') }}</p><p class="text-body-2 font-weight-medium mb-0">{{ requisition.requested_by?.name ?? '—' }}</p></VCol></VRow></VCardText></VCard>
        <VCard elevation="0" border class="mb-4" style="border-radius: 12px;"><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold"><VIcon icon="tabler-file-text" size="18" color="primary" class="me-2" />{{ t('recruitment_requisition_pages.section_position_details') }}</VCardTitle><VCardText class="pa-5 pt-0"><div class="mb-4"><p class="text-caption text-medium-emphasis mb-2">{{ t('recruitment_requisition_pages.field_reason') }}</p><p class="text-body-2 mb-0" style="white-space: pre-wrap;">{{ requisition.reason }}</p></div><template v-if="requisition.job_description"><VDivider class="mb-4" /><div class="mb-4"><p class="text-caption text-medium-emphasis mb-2">{{ t('recruitment_requisition_pages.field_job_description') }}</p><p class="text-body-2 mb-0" style="white-space: pre-wrap;">{{ requisition.job_description }}</p></div></template><template v-if="requisition.required_qualifications"><VDivider class="mb-4" /><div><p class="text-caption text-medium-emphasis mb-2">{{ t('recruitment_requisition_pages.field_qualifications') }}</p><p class="text-body-2 mb-0" style="white-space: pre-wrap;">{{ requisition.required_qualifications }}</p></div></template></VCardText></VCard>
        <VCard v-if="requisition.required_skills && requisition.required_skills.length" elevation="0" border class="mb-4" style="border-radius: 12px;"><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold"><VIcon icon="tabler-tags" size="18" color="primary" class="me-2" />{{ t('recruitment_requisition_pages.section_skills') }}</VCardTitle><VCardText class="pa-5 pt-2"><div class="d-flex flex-wrap gap-2"><VChip v-for="skill in requisition.required_skills" :key="skill" size="small" color="primary" variant="tonal" label>{{ skill }}</VChip></div></VCardText></VCard>
        <VCard v-if="requisition.salary_band_min !== null || requisition.salary_band_max !== null" elevation="0" border class="mb-4" style="border-radius: 12px;"><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold"><VIcon icon="tabler-currency-dollar" size="18" color="primary" class="me-2" />{{ t('recruitment_requisition_pages.section_compensation') }}</VCardTitle><VCardText class="pa-5 pt-0"><VRow dense><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1">Minimum</p><p class="text-body-1 font-weight-semibold mb-0">{{ formatCurrency(requisition.salary_band_min) }}</p></VCol><VCol cols="12" sm="6"><p class="text-caption text-medium-emphasis mb-1">Maximum</p><p class="text-body-1 font-weight-semibold mb-0">{{ formatCurrency(requisition.salary_band_max) }}</p></VCol></VRow></VCardText></VCard>
        <VAlert v-if="requisition.approval_notes" type="success" variant="tonal" class="mb-4"><p class="text-caption font-weight-semibold mb-1">{{ t('recruitment_requisition_pages.field_approval_notes') }}</p><p class="text-body-2 mb-0">{{ requisition.approval_notes }}</p></VAlert>
        <VAlert v-if="requisition.rejection_reason" type="error" variant="tonal" class="mb-4"><p class="text-caption font-weight-semibold mb-1">{{ t('recruitment_requisition_pages.field_rejection_reason_label') }}</p><p class="text-body-2 mb-0">{{ requisition.rejection_reason }}</p></VAlert>
      </VCol>
      <VCol cols="12" lg="4">
        <div style="position: sticky; top: 80px;">
          <VCard elevation="0" border class="mb-4" style="border-radius: 12px;"><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold">{{ t('recruitment_requisition_pages.timeline_title') }}</VCardTitle><VCardText class="pa-5 pt-0"><div class="d-flex flex-column gap-3">
            <div class="d-flex align-start gap-3"><div class="d-flex align-center justify-center rounded-circle flex-shrink-0 mt-1" style="width: 28px; height: 28px; background: rgba(115,103,240,0.12);"><VIcon icon="tabler-circle-plus" size="14" color="primary" /></div><div><p class="text-body-2 font-weight-medium mb-0">{{ t('recruitment_requisition_pages.timeline_created') }}</p><p class="text-caption text-medium-emphasis mb-0">{{ formatDate(requisition.created_at) }}</p></div></div>
            <div v-if="requisition.submitted_at" class="d-flex align-start gap-3"><div class="d-flex align-center justify-center rounded-circle flex-shrink-0 mt-1" style="width: 28px; height: 28px; background: rgba(0,207,232,0.12);"><VIcon icon="tabler-send" size="14" color="info" /></div><div><p class="text-body-2 font-weight-medium mb-0">{{ t('recruitment_requisition_pages.timeline_submitted') }}</p><p class="text-caption text-medium-emphasis mb-0">{{ formatDate(requisition.submitted_at) }}</p></div></div>
            <div v-if="requisition.approved_at" class="d-flex align-start gap-3"><div class="d-flex align-center justify-center rounded-circle flex-shrink-0 mt-1" style="width: 28px; height: 28px; background: rgba(40,199,111,0.12);"><VIcon icon="tabler-circle-check" size="14" color="success" /></div><div><p class="text-body-2 font-weight-medium mb-0">{{ t('recruitment_requisition_pages.timeline_approved') }}</p><p class="text-caption text-medium-emphasis mb-0">{{ formatDate(requisition.approved_at) }}<span v-if="requisition.approved_by"> · {{ requisition.approved_by.name }}</span></p></div></div>
            <div v-if="requisition.rejected_at" class="d-flex align-start gap-3"><div class="d-flex align-center justify-center rounded-circle flex-shrink-0 mt-1" style="width: 28px; height: 28px; background: rgba(255,71,87,0.12);"><VIcon icon="tabler-circle-x" size="14" color="error" /></div><div><p class="text-body-2 font-weight-medium mb-0">{{ t('recruitment_requisition_pages.timeline_rejected') }}</p><p class="text-caption text-medium-emphasis mb-0">{{ formatDate(requisition.rejected_at) }}<span v-if="requisition.approved_by"> · {{ requisition.approved_by.name }}</span></p></div></div>
            <div v-if="requisition.converted_at" class="d-flex align-start gap-3"><div class="d-flex align-center justify-center rounded-circle flex-shrink-0 mt-1" style="width: 28px; height: 28px; background: rgba(134,110,246,0.12);"><VIcon icon="tabler-briefcase" size="14" color="secondary" /></div><div><p class="text-body-2 font-weight-medium mb-0">{{ t('recruitment_requisition_pages.timeline_converted') }}</p><p class="text-caption text-medium-emphasis mb-0">{{ formatDate(requisition.converted_at) }}</p></div></div>
          </div></VCardText></VCard>
          <VCard elevation="0" border style="border-radius: 12px;"><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold">{{ t('recruitment_requisition_pages.details_title') }}</VCardTitle><VCardText class="pa-5 pt-0"><div class="d-flex flex-column gap-3">
            <div class="d-flex align-center justify-space-between"><span class="text-caption text-medium-emphasis">{{ t('recruitment_requisition_pages.details_status') }}</span><VChip :color="requisition.status.color" size="x-small" label variant="tonal" class="font-weight-medium">{{ requisition.status.label }}</VChip></div><VDivider />
            <div class="d-flex align-center justify-space-between"><span class="text-caption text-medium-emphasis">{{ t('recruitment_requisition_pages.details_number') }}</span><span class="text-body-2 font-weight-medium">{{ requisition.requisition_number }}</span></div><VDivider />
            <div class="d-flex align-center justify-space-between"><span class="text-caption text-medium-emphasis">{{ t('recruitment_requisition_pages.details_job_type') }}</span><span class="text-body-2">{{ requisition.job_type.label }}</span></div><VDivider />
            <div class="d-flex align-center justify-space-between"><span class="text-caption text-medium-emphasis">{{ t('recruitment_requisition_pages.details_headcount') }}</span><span class="text-body-2 font-weight-medium">{{ requisition.headcount }}</span></div>
          </div></VCardText></VCard>
        </div>
      </VCol>
    </VRow>

    <VDialog v-model="approveDialog" max-width="480" persistent><VCard><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold">{{ t('recruitment_requisition_pages.dialog_approve_title') }}</VCardTitle><VCardText class="pa-5 pt-0"><p class="text-body-2 text-medium-emphasis mb-4">{{ t('recruitment_requisition_pages.dialog_approve_text', { number: requisition.requisition_number, title: requisition.title }) }}</p><VTextarea v-model="approveNotes" :label="t('recruitment_requisition_pages.dialog_approve_notes')" variant="outlined" density="comfortable" rows="3" :placeholder="t('recruitment_requisition_pages.dialog_approve_notes_placeholder')" hide-details /></VCardText><VCardActions class="pa-5 pt-0 gap-2"><VSpacer /><VBtn variant="text" color="default" :disabled="submitting" @click="approveDialog = false">{{ t('recruitment_requisition_pages.cancel') }}</VBtn><VBtn color="success" variant="flat" :loading="submitting" @click="submitApprove"><VIcon icon="tabler-check" size="18" class="me-1" />{{ t('recruitment_requisition_pages.confirm_approval') }}</VBtn></VCardActions></VCard></VDialog>
    <VDialog v-model="rejectDialog" max-width="480" persistent><VCard><VCardTitle class="pa-5 pb-2 text-body-1 font-weight-semibold">{{ t('recruitment_requisition_pages.dialog_reject_title') }}</VCardTitle><VCardText class="pa-5 pt-0"><p class="text-body-2 text-medium-emphasis mb-4">{{ t('recruitment_requisition_pages.dialog_reject_text', { number: requisition.requisition_number, title: requisition.title }) }}</p><VTextarea v-model="rejectReason" :label="t('recruitment_requisition_pages.dialog_reject_reason')" variant="outlined" density="comfortable" rows="3" :placeholder="t('recruitment_requisition_pages.dialog_reject_reason_placeholder')" hide-details="auto" /></VCardText><VCardActions class="pa-5 pt-0 gap-2"><VSpacer /><VBtn variant="text" color="default" :disabled="submitting" @click="rejectDialog = false">{{ t('recruitment_requisition_pages.cancel') }}</VBtn><VBtn color="error" variant="flat" :loading="submitting" :disabled="!rejectReason.trim()" @click="submitReject"><VIcon icon="tabler-x" size="18" class="me-1" />{{ t('recruitment_requisition_pages.confirm_rejection') }}</VBtn></VCardActions></VCard></VDialog>
  </div>
</template>
